package com.hmdp.ai.domain.workflow;
import com.fasterxml.jackson.databind.ObjectMapper;import com.hmdp.ai.shared.validation.*;import org.junit.jupiter.api.Test;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
class WorkflowValidatorTest {@Test void acceptsReachableAcyclicWorkflow(){WorkflowDefinition w=workflow(Arrays.asList(node("s",WorkflowNodeType.START,"{}"),node("e",WorkflowNodeType.END,"{}")),Collections.singletonList(edge("s","e",null)));assertTrue(validator().validate(w).isValid());}@Test void rejectsIllegalCycleAndMissingEnd(){WorkflowDefinition w=workflow(Arrays.asList(node("s",WorkflowNodeType.START,"{}"),node("a",WorkflowNodeType.TEXT_TRANSFORM,"{}")),Arrays.asList(edge("s","a",null),edge("a","s",null)));ValidationResult r=validator().validate(w);assertFalse(r.isValid());assertTrue(r.getIssues().stream().anyMatch(i->"WORKFLOW_ILLEGAL_CYCLE".equals(i.getCode())));assertTrue(r.getIssues().stream().anyMatch(i->"WORKFLOW_END_REQUIRED".equals(i.getCode())));}private WorkflowValidator validator(){ObjectMapper m=new ObjectMapper();return new WorkflowValidator(new JsonSchemaValidationService(m),new ConditionDslEvaluator(m),m);}private WorkflowDefinition workflow(List<WorkflowNodeDefinition>n,List<WorkflowEdgeDefinition>e){return new WorkflowDefinition("v","t","w","wf",1,"{\"type\":\"object\"}","{\"type\":\"object\"}","{\"type\":\"object\"}","{}","DRAFT",n,e);}private WorkflowNodeDefinition node(String c,WorkflowNodeType t,String cfg){return new WorkflowNodeDefinition(c,c,t,c,cfg,"{}","{}",1000,1);}private WorkflowEdgeDefinition edge(String s,String t,String c){return new WorkflowEdgeDefinition(s+t,s,t,c,0,null);}}
